cd /scr/wurgaft/auto-psych/agent_trees/962b9e6d929c436d/repo/_runs/cell_1/experiment2/model_loop; python3 -c "
exec(open('models/span_restricted_rule_concepts.py').read().split('with pm.Model')[0].replace('import pymc as pm','').replace('import pytensor.tensor as pt',''))
import csv
sets=set(tuple(int(x) for x in r['number_set'].split(',')) for r in csv.DictReader(open('responses.csv')))
for b in [1,2,3,5]:
  g=set()
  for st in sets:
    for m in BASE_MEMBERS:
      L=len(m); isx=[v in st for v in m]
      cum=[0]
      for v in isx: cum.append(cum[-1]+v)
      for s in range(2,L):
        for a in range(L-s+1):
          k=cum[a+s]-cum[a]
          if k: g.add((s,(m[a+s-1]-m[a])//b,k))
  print(b,len(g))"

